from pathlib import Path
import json
b=Path(__file__).resolve().parent;root=b.parents[1]
def load(p):return json.loads((b/p).read_text())
runs=load('part3-runtime/latency-runs.json');memory=load('part3-runtime/summary.json');deltas={r['config']:r for r in load('runtime-screen/summary.json')}
selected={name:min((r for r in runs if r['name']==name),key=lambda r:r['mean_ms']) for name in deltas}
assert len(runs)==30 and all(len([r for r in runs if r['name']==n])==3 for n in selected)
lines=['# Phần 3 — Tối ưu SmolVLA không cần train','','## Phạm vi và protocol','','Không thay GGUF gốc. Runtime flags dùng cùng checkpoint; quantization xuất sáu file riêng, không train, không pruning.','Latency: vla-bench, 2 ảnh512×512,16token,3warmup+20reps,3process/config. Chọn cả lượt có mean thấp nhất; p50/p90 thuộc cùng lượt. Bộ nhớ lấy peak lớn nhất trong3process/config, đo bằng nsys riêng với cùng workload.','Output: vla_predict_check,2ảnh512,6token theo harness, noise cố định; so với defaults. Max abs và RMSE trên50×7 action thực, loại padding32chiều. Đây là input khác benchmark; không suy ra SR từ độ lệch synthetic.','','## Runtime flags','','| Cấu hình | File MiB | Mean / p50 / p90 ms | Peak allocation MiB | Max abs real7 | RMSE real7 |','|---|---:|---:|---:|---:|---:|']
size=Path('/home/doris/.cache/vla/vrfai/smolvla-libero-gguf/smolvla-libero.gguf').stat().st_size/1048576
for n,r in selected.items():
 d=deltas[n];lines.append(f"| {n} | {size:.2f} | {r['mean_ms']:.1f} / {r['p50_ms']:.1f} / {r['p90_ms']:.1f} | {memory[n]['peak_MiB']:.2f} | {d['max_abs_real7']:.8g} | {d['rmse_real7']:.8g} |")
lines+=['','Flags chính xác của mỗi cấu hình nằm trong `part3-runtime/latency-runs.json`. bf16/f16 chỉ đổi weight dtype; activation giữ mặc định F32. Không thử act-dtype BF16 cho SmolVLA vì docs giới hạn flag này cho các kiến trúc khác. steps-5/3 đổi số bước solver; các cấu hình khác giữ10bước.','','## Quantization — runtime defaults','','| Model | File MiB | Mean / p50 / p90 ms | Peak allocation MiB | Max abs real7 | RMSE real7 |','|---|---:|---:|---:|---:|---:|']
bench=load('candidate-bench/selected.json');mem=load('memory-all/summary.json');checks={r['name']:r for r in load('candidate-checks/summary.json')}
for n,r in bench.items():
 if n!='defaults' and not any(q in n for q in ['q8_0','q5_0','q4_0']):continue
 d=checks[n];sz=Path(r['model']).stat().st_size/1048576
 lines.append(f"| {n} | {sz:.2f} | {r['mean_ms']:.1f} / {r['p50_ms']:.1f} / {r['p90_ms']:.1f} | {mem[n]['peak_MiB']:.2f} | {d['max_abs_real7']:.8g} | {d['rmse_real7']:.8g} |")
lines+=['','Quantization theo scripts/quantize_gguf.py trong docs/MODELS.md. `lm` gồm225tensor (VLM và connector mm.fc1); `vision` thêm72tensor. Action expert289tensor giữ float. Chi tiết kích thước byte, SHA256 và command ở `quantization/manifest.json`.','','## Điều kiện đo và giới hạn','','RTX3060Laptop6GiB, WSL2; laptop cắm sạc, chế độ nguồn bình thường, không tản nhiệt ngoài theo người dùng. Đợt runtime bổ sung từ chối chạy nếu còn vla-server; không khẳng định loại hết ứng dụng Windows. Số đo quantization là batch trước, có control cùng batch; không ghép batch để suy ra chênh lệch nhỏ.','WSL báo N/A cho process resident VRAM. Cột bộ nhớ là peak traced device allocation (Device+DeviceStatic), không bao hết context/driver hoặc allocation không được ghi nhận. Không coi đây là toàn bộ peak resident VRAM.','Hai CUDA tests bit-exact còn fail; baseline giữ defaults theo lựa chọn người dùng. Fused/unfused có sai lệch đã ghi riêng. Không gán đảm bảo bit-exact trong docs thành kết quả đã xác nhận trên máy này.','','## Nguồn dữ liệu và tái lập','','- Runtime: part3_runtime_children.py, run_part3.sh, part3-runtime/*, audit_part3_memory.py.','- Quantization: prepare_quantized.py, quantization/manifest.json, candidate-bench/selected.json, candidate-checks/summary.json, memory-all/summary.json.','- Docs repo: docs/USAGE.md, docs/backend/cuda.md, docs/MODELS.md.','- Không kết luận SR trong phần này. Đánh giá LIBERO thuộc phần4.']
best=min(selected.values(),key=lambda r:r['mean_ms']);control=selected['defaults']
lines+=['','## Nhận xét từ số đo',f"- Runtime nhanh nhất trong tập thử: {best['name']}, mean {best['mean_ms']:.1f}ms; giảm {(1-best['mean_ms']/control['mean_ms'])*100:.2f}% so với control cùng batch. Cần đọc kèm độ lệch action; không xem giảm solver steps là miễn phí chất lượng.",'- File runtime không đổi kích thước vì dùng cùng GGUF; resident weight dtype thay đổi trong bộ nhớ.', '- Quantization giảm rõ kích thước và allocation; latency cần so với defaults của chính candidate-bench. Không suy ra tốc độ chỉ từ số bit.', '- Output synthetic không chứng minh giữ khả năng điều khiển. Phần3 hoàn tất phép đo, chưa chốt cấu hình triển khai theo SR.']
p=root/'PART3_OPTIMIZATION.md' ;p.write_text('\n'.join(lines)+'\n');print('Wrote',p)
